    code: "\n\t#define c30 0.86602540378\n\t#define hm  1.33333333333\n\t#define grid 16.0\n\t#define smooth 0.02\n\t#define timeScale 0.1\n\tvec2 hex(vec2 v){\n\t\tfloat yc = abs(mod(v.x + floor((v.y*hm + 0.5))*(c30 / 2.0),c30) / c30 - 0.5);\n\t\tfloat y = floor(v.y*hm + yc);\n\t\tfloat x = floor(v.x/c30 + 0.5 + fract(y /  2.0))- fract(y / 2.0);\n\t\treturn vec2(x*c30,y /hm + 1.0/(hm * 4.0));\n\t}\n\tvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n\t\tfloat wave =  texture(iChannel0, vec2(0.0,1.0)).x;\n\t\tfloat wave2 = texture(iChannel0, vec2(0.0,.1)).x;\n\t\tvec2 uv = fragCoord.xy / vec2(iResolution.y,iResolution.y);\n\t  \tuv.x -= .5;\n\t\tfloat rt = iTime * timeScale;\n\t\tvec2 gv = hex(uv*grid)/grid;\n\t\tvec2 mv = gv - 0.5;\n\t\tvec2 rv = vec2(((atan(mv.x,mv.y)/3.141526) + cos(iTime + wave2)) / 2.0, length(mv * sin(iTime + wave2)));\n\t\tfloat fv = fract((rv.x- rt) * cos(gv.x /20.0) * 2.0 + rv.y * 2.0);\n\t\tfloat dist = length(uv - gv) * grid;\n\t\tfloat dist2 = 1.0 - smoothstep(-smooth,0.0,dist - c30/2.);\n\t\tdist += fv + wave2;\n\t\tdist += cos(wave / 2.);\n\t\tdist = smoothstep(0.5,0.5 + smooth,fract(dist));\n\t\tfloat finCol = float(0.5);\n\t\tfinCol = mix(finCol, dist, dist2);\n\t\tfragColor = vec4(finCol) + vec4(cos(iTime + dist2 + wave2) + wave2, sin(fv * wave) * .5, sin(uv.x * 3.),  1.0);\n\t}"
