    name: "Heart",
    id: 1,
    code: "\n\t#define POINT_COUNT 8\n\n\tvec2 points[POINT_COUNT];\n\tconst float speed = -0.5;\n\tconst float len = 0.25;\n\tconst float scale = 0.012;\n\tfloat intensity = 1.3;\n\tfloat radius = 0.015;\n\tfloat sdBezier(vec2 pos, vec2 A, vec2 B, vec2 C){\n\t\tvec2 a = B - A;\n\t\tvec2 b = A - 2.0*B + C;\n\t\tvec2 c = a * 2.0;\n\t\tvec2 d = A - pos;\n\t\tfloat kk = 1.0 / dot(b,b);\n\t\tfloat kx = kk * dot(a,b);\n\t\tfloat ky = kk * (2.0*dot(a,a)+dot(d,b)) / 3.0;\n\t\tfloat kz = kk * dot(d,a);\n\t\tfloat res = 0.0;\n\t\tfloat p = ky - kx*kx;\n\t\tfloat p3 = p*p*p;\n\t\tfloat q = kx*(2.0*kx*kx - 3.0*ky) + kz;\n\t\tfloat h = q*q + 4.0*p3;\n\t\tif(h >= 0.0){\n\t\t\th = sqrt(h);\n\t\t\tvec2 x = (vec2(h, -h) - q) / 2.0;\n\t\t\tvec2 uv = sign(x)*pow(abs(x), vec2(1.0/3.0));\n\t\t\tfloat t = uv.x + uv.y - kx;\n\t\t\tt = clamp( t, 0.0, 1.0 );\n\t\t\tvec2 qos = d + (c + b*t)*t;\n\t\t\tres = length(qos);\n\t\t}else{\n\t\t\tfloat z = sqrt(-p);\n\t\t\tfloat v = acos( q/(p*z*2.0) ) / 3.0;\n\t\t\tfloat m = cos(v);\n\t\t\tfloat n = sin(v)*1.732050808;\n\t\t\tvec3 t = vec3(m + m, -n - m, n - m) * z - kx;\n\t\t\tt = clamp( t, 0.0, 1.0 );\n\t\t\tvec2 qos = d + (c + b*t.x)*t.x;\n\t\t\tfloat dis = dot(qos,qos);\n\t\t\tres = dis;\n\t\t\tqos = d + (c + b*t.y)*t.y;\n\t\t\tdis = dot(qos,qos);\n\t\t\tres = min(res,dis);\n\t\t\tqos = d + (c + b*t.z)*t.z;\n\t\t\tdis = dot(qos,qos);\n\t\t\tres = min(res,dis);\n\t\t\tres = sqrt( res );\n\t\t}\n\t\treturn res;\n\t}\n\tvec2 getHeartPosition(float t){\n\t\treturn vec2(16.0 * sin(t) * sin(t) * sin(t),\n\t\t\t\t\t-(13.0 * cos(t) - 5.0 * cos(2.0*t)\n\t\t\t\t\t- 2.0 * cos(3.0*t) - cos(4.0*t)));\n\t}\n\tfloat getGlow(float dist, float radius, float intensity){\n\t\treturn pow(radius/dist, intensity);\n\t}\n\tfloat getSegment(float t, vec2 pos, float offset){\n\t\tfor(int i = 0; i < POINT_COUNT; i++){\n\t\t\tpoints[i] = getHeartPosition(offset + float(i)*len + fract(speed * t) * 6.28);\n\t\t}\n\t\tvec2 c = (points[0] + points[1]) / 2.0;\n\t\tvec2 c_prev;\n\t\tfloat dist = 10000.0;\n\t\tfor(int i = 0; i < POINT_COUNT-1; i++){\n\t\t\tc_prev = c;\n\t\t\tc = (points[i] + points[i+1]) / 2.0;\n\t\t\tdist = min(dist, sdBezier(pos, scale * c_prev, scale * points[i], scale * c));\n\t\t}\n\t\treturn max(0.0, dist);\n\t}\n\tvoid mainImage( out vec4 fragColor, in vec2 fragCoord ){\n\t\tvec2 uv = fragCoord/iResolution.xy;\n\t\tfloat widthHeightRatio = iResolution.x/iResolution.y;\n\t\tvec2 centre = vec2(0.5, 0.5);\n\t\tvec2 pos = centre - uv;\n\t\tpos.y /= widthHeightRatio;\n\t\tpos.y += 0.03;\n\t\tfloat t = iTime;\n\t\tfloat dist = getSegment(t, pos, 0.0);\n\t\tfloat glow = getGlow(dist, radius, intensity);\n\t\tvec3 col = vec3(0.0);\n\t\tcol += 10.0*vec3(smoothstep(0.006, 0.003, dist));\n\t\tcol += glow * vec3(1.0,0.05,0.3);\n\t\tdist = getSegment(t, pos, 3.4);\n\t\tglow = getGlow(dist, radius, intensity);\n\t\tcol += 10.0*vec3(smoothstep(0.006, 0.003, dist));\n\t\tcol += glow * vec3(0.1,0.4,1.0);\n\t\tcol = 1.0 - exp(-col);\n\t\tcol = pow(col, vec3(0.4545));\n\t\tfragColor = vec4(col,1.0);\n\t}\n\t"
